		private void OnUpdate(float deltaTime) {
            if (UIManager.Instance.GetCurrentUIWindow<UIWindow>() != this || isWaitUpdate || msgWindowController.OnUpdate(deltaTime))
                return;

            if (wazaSelectPanel.IsShow)
            {
                wazaSelectPanel.OnUpdate(deltaTime);
                return;
            }

            if (bagItemPanel.IsShowSelectAmount)
            {
                OnUpdateSelectAmount();
                return;
            }

            if (isWaitPokemonParty)
            {
                OnUpdatePokemonParty(deltaTime);
                return;
            }

            OnUpdateDefault();
        }
		private void OnUpdateDefault() {
            if (IsRepeatButton(UIManager.StickLLeft, false))
            {
                bagItemPanel.MoveCategorySelect(-1);
                UpdateKeyGuide();
                return;
            }
            if (IsRepeatButton(UIManager.StickLRight, false))
            {
                bagItemPanel.MoveCategorySelect(1);
                UpdateKeyGuide();
                return;
            }
            if (IsReleaseButton(UIManager.StickLLeft, false) || IsReleaseButton(UIManager.StickLRight, false))
                bagItemPanel.ResumeCategoryMoveSelect();

            if (IsRepeatButton(UIManager.StickLUp, false))
            {
                bagItemPanel.MoveItemListSelect(-1);
                return;
            }
            if (IsRepeatButton(UIManager.StickLDown, false))
            {
                bagItemPanel.MoveItemListSelect(1);
                return;
            }
            if (IsRepeatButton(GameController.ButtonMask.L, false))
            {
                bagItemPanel.MoveItemListPage(false);
                return;
            }
            if (IsRepeatButton(GameController.ButtonMask.R, false))
            {
                bagItemPanel.MoveItemListPage(true);
                return;
            }
            if (IsReleaseButton(UIManager.StickLUp, false) || IsReleaseButton(UIManager.StickLDown, false) ||
                IsReleaseButton(GameController.ButtonMask.L, false) || IsReleaseButton(GameController.ButtonMask.R, false))
                bagItemPanel.ResumeItemListMoveSelect();

            if (IsPushButton(UIManager.ButtonA, false))
            {
                if (bagItemPanel.IsNoItem || bagItemPanel.SelectedItemButton == null)
                    return;

                bagItemPanel.PlayCursorDecideAnimation();
                ItemInfo item = bagItemPanel.SelectedItemButton.GetInfo();
                if (onSelectedKinomiItem != null)
                {
                    KinomiInfo kinomiInfo = new KinomiInfo(item);
                    onSelectedKinomiItem(kinomiInfo.Id);
                    Close(onClosed, _prevWindowId, true);
                }
                else
                {
                    ShowItemContextMenu(item);
                }
                AudioManager.Instance.PlaySe(AK.EVENTS.UI_COMMON_DECIDE, null);
            }
            else if (IsPushButton(UIManager.ButtonB, false))
            {
                Close(onClosed, _prevWindowId, true);
            }
            else if (IsPushButton(UIManager.ButtonX, false))
            {
                if (canSort)
                    StartSortItems();
            }
            else if (IsPushButton(UIManager.ButtonY, false))
            {
                if (canSwitchFavorite)
                    SwitchSelectedItemFavorite();
            }
            else if (IsPushButton(BagItemPanel.SwitchItemDescriptionWazaPanelButton, false) && bagItemPanel.CanSwitchDescriptionWazaPanel)
            {
                bagItemPanel.SwitchItemDescriptionWazaPanel();
            }
        }
		private void OnUpdateSelectAmount() {
            if (IsRepeatButton(UIManager.StickLLeft, false))
                bagItemPanel.ChangeSelectAmount(false, true);
            else if (IsRepeatButton(UIManager.StickLRight, false))
                bagItemPanel.ChangeSelectAmount(true, true);
            else if (IsReleaseButton(UIManager.StickLLeft, false) || IsReleaseButton(UIManager.StickLRight, false))
                bagItemPanel.ResumeSelectAmountChange();

            if (IsRepeatButton(UIManager.StickLUp, false))
                bagItemPanel.ChangeSelectAmount(true, false);
            else if (IsRepeatButton(UIManager.StickLDown, false))
                bagItemPanel.ChangeSelectAmount(false, false);
            else if (IsReleaseButton(UIManager.StickLUp, false) || IsReleaseButton(UIManager.StickLDown, false))
                bagItemPanel.ResumeSelectAmountChange();

            if (IsPushButton(UIManager.ButtonA, false))
                bagItemPanel.DecideSelectAmount();
            else if (IsPushButton(UIManager.ButtonB, false))
                bagItemPanel.CancelSelectAmount();
        }
		private void OnUpdatePokemonParty(float deltaTime) {
            if (!pokemonParty.OnUpdate(deltaTime, _input) && isWaitPokemonParty && IsPushButton(UIManager.ButtonB, false))
                EndSelectPokemonParty();
        }
		private void UpdateKeyGuide() {
            var param = new Keyguide.Param();
            if (isWaitPokemonParty)
            {
                param.itemParams.Add(new KeyguideItem.Param() { keyguideId = KeyguideID.BAG_ITEMLIST_DECIDE });
                param.itemParams.Add(new KeyguideItem.Param() { keyguideId = KeyguideID.BAG_ITEMLIST_BACK });
            }
            else
            {
                if (!bagItemPanel.IsNoItem)
                    param.itemParams.Add(new KeyguideItem.Param() { keyguideId = KeyguideID.BAG_ITEMLIST_DECIDE });
                if (canSort)
                    param.itemParams.Add(new KeyguideItem.Param() { keyguideId = KeyguideID.BAG_ITEMLIST_SORT });
                if (canSwitchFavorite)
                    param.itemParams.Add(new KeyguideItem.Param() { keyguideId = KeyguideID.BAG_ITEMLIST_FAVORITE });
                if (bagItemPanel.CanSwitchDescriptionWazaPanel)
                    param.itemParams.Add(new KeyguideItem.Param() { keyguideId = KeyguideID.SHOP_FRIENDLY_DESCRIPTION });
                param.itemParams.Add(new KeyguideItem.Param() { keyguideId = KeyguideID.BAG_ITEMLIST_BACK });
            }

            Keyguide keyguide = UIManager.Instance.GetKeyguide(null, true);
            if (keyguide == null)
                return;

            keyguide.transform.SetParent(transform, false);
            if (effectRoot != null)
                effectRoot.SetAsLastSibling();
            keyguide.Open(param);
        }
		private void SetupBagItemPanel() {
            ItemInfo.CategoryType[] categoryTypes;
            switch (bootType)
            {
                case BootType.Pokemon:
                    categoryTypes = new ItemInfo.CategoryType[] { ItemInfo.CategoryType.Heal, ItemInfo.CategoryType.Nuts };
                    break;
                case BootType.Status:
                case BootType.WazaMachine:
                    categoryTypes = new ItemInfo.CategoryType[] { ItemInfo.CategoryType.WazaMachine };
                    break;
                case BootType.Poffine:
                    categoryTypes = new ItemInfo.CategoryType[] { ItemInfo.CategoryType.Nuts };
                    break;
                case BootType.Battle:
                case BootType.BattleAutoPilot:
                    if (modeType == ModeType.Recovery)
                        categoryTypes = new ItemInfo.CategoryType[] { ItemInfo.CategoryType.Heal, ItemInfo.CategoryType.Nuts };
                    else
                        categoryTypes = new ItemInfo.CategoryType[] { ItemInfo.CategoryType.Heal, ItemInfo.CategoryType.Ball, ItemInfo.CategoryType.Battle, ItemInfo.CategoryType.Nuts };
                    break;
                case BootType.Important:
                    categoryTypes = new ItemInfo.CategoryType[] { ItemInfo.CategoryType.Important };
                    break;
                default:
                    categoryTypes = null;
                    break;
            }

            bagItemPanel.Initialize(ItemWork.GetItemListMemory(bootType), isBattle, categoryTypes);
            if (displayMoney >= 0)
                bagItemPanel.SetMoneyText(displayMoney);
        }
		private void SetupBattleBootParam() {
            battleBootParam.IsTrainerBattle = BattleViewCore.Instance.ViewSystem.GetMainModule().GetCompetitor(true) != BtlCompetitor.BTL_COMPETITOR_WILD;
            battleBootParam.isDouble = false;
            if (BattleViewCore.Instance.ViewSystem.GetMainModule().GetRule() == BtlRule.BTL_RULE_DOUBLE)
            {
                BtlMultiMode multiMode = BattleViewCore.Instance.ViewSystem.GetMainModule().GetMultiMode();
                battleBootParam.isDouble = multiMode == BtlMultiMode.BTL_MULTIMODE_NONE || multiMode == BtlMultiMode.BTL_MULTIMODE_P_AA;
            }

            BTL_PARTY party = BattleViewCore.Instance.ViewSystem.GetBattleParty_Self();
            battleBootParam.TopMemberIndex = 0;
            BTL_POKEPARAM topMember = party.GetAliveTopMember();
            if (topMember != null)
                battleBootParam.TopMemberIndex = party.FindMember(topMember);

            if (onlyViewPokemonParam != null)
            {
                battleBootParam.SasiosaeFlags = new bool[1];
                for (byte i = 0; i < party.GetMemberCount(); i++)
                {
                    BTL_POKEPARAM bpp = party.GetMemberData(i);
                    PokemonParam srcData = bpp.GetSrcData();
                    if (srcData.GetID() == onlyViewPokemonParam.GetID() && srcData.GetPersonalRnd() == onlyViewPokemonParam.GetPersonalRnd())
                    {
                        battleBootParam.SasiosaeFlags[0] = bpp.CheckSick(WazaSick.WAZASICK_SASIOSAE);
                        onlyViewBattlePokemonId = bpp.GetID();
                        return;
                    }
                }
            }
            else
            {
                battleBootParam.SasiosaeFlags = new bool[party.GetMemberCount()];
                for (int i = 0; i < party.GetMemberCount(); i++)
                {
                    BTL_POKEPARAM bpp = party.GetMemberData((byte)i);
                    battleBootParam.SasiosaeFlags[i] = bpp.CheckSick(WazaSick.WAZASICK_SASIOSAE);
                }
            }
        }
		private void OnChangeBagPanelSelectItem(global::Dpr.UI.BagItemButton bagItemButton) {
            if (bagItemButton == null)
            {
                foreach (PokemonPartyItem partyItem in pokemonParty.items)
                    partyItem.HideUsableItemText();
                return;
            }

            ItemInfo itemInfo = bagItemButton.GetInfo();
            ushort itemNo = (ushort)itemInfo.Id;
            ItemData.FieldFunctionType fieldFunctionType = itemInfo.GetFieldFunctionType();
            uint machineNo;
            WazaNo wazaNo;
            if (fieldFunctionType == ItemData.FieldFunctionType.ITEMUSE_FLD_WAZA)
            {
                machineNo = ItemData.GetWazaMashineNo(itemNo);
                wazaNo = ItemData.GetWazaNo(itemNo);
            }
            else
            {
                wazaNo = WazaNo.NULL;
                machineNo = 0;
            }

            MonsNo nextMonsNo = 0;
            uint rootNum = 0;
            EvolveSituation evolveSituation = new EvolveSituation();
            foreach (PokemonPartyItem partyItem in pokemonParty.items)
            {
                if (fieldFunctionType == ItemData.FieldFunctionType.ITEMUSE_FLD_WAZA)
                {
                    if (partyItem.param.pokemonParam.CheckWazaMachine(machineNo))
                    {
                        if (partyItem.param.pokemonParam.GetWazaIndex(wazaNo) == 4)
                            partyItem.ShowUsableItemText("SS_bag_050");
                        else
                            partyItem.ShowUsableItemText("SS_bag_052");
                    }
                    else
                    {
                        partyItem.ShowUsableItemText("SS_bag_051");
                    }
                }
                else if (fieldFunctionType == ItemData.FieldFunctionType.ITEMUSE_FLD_EVOLUTION)
                {
                    if (partyItem.param.pokemonParam.CanEvolveByItem(evolveSituation, itemNo, ref nextMonsNo, ref rootNum))
                        partyItem.ShowUsableItemText("SS_bag_053");
                    else
                        partyItem.ShowUsableItemText("SS_bag_054");
                }
                else
                {
                    partyItem.HideUsableItemText();
                }
            }
        }
		private void CreatePokemonPartyParam(int selectIndex = 0) {
            pokemonPartyParam = new PokemonParty.Param();
            pokemonPartyParam.selectIndex = selectIndex;

            if (isBattle)
            {
                BTL_PARTY party = BattleViewCore.Instance.ViewSystem.GetBattleParty_Self();
                if (onlyViewPokemonParam != null)
                {
                    onlyViewPartyIndex = party.GetMemberIndex((byte)onlyViewBattlePokemonId);
                    var itemParam = new PokemonPartyItem.Param()
                    {
                        showItemName = false,
                        pokemonParam = onlyViewPokemonParam,
                        battle = new PokemonPartyItem.Param.Battle() { battlePokemonParam = party.GetMemberData((byte)onlyViewPartyIndex) },
                    };
                    pokemonPartyParam.itemParams.Add(itemParam);
                }
                else
                {
                    if (_prevWindowId == WINDOWID_FIELD)
                        UIManager.CreatePokemonParamsByBattle();

                    int memberCount = party.GetMemberCount();
                    for (int i = 0; i < memberCount; i++)
                    {
                        var itemParam = new PokemonPartyItem.Param()
                        {
                            showItemName = false,
                            battle = new PokemonPartyItem.Param.Battle() { battlePokemonParam = party.GetMemberData((byte)i) },
                        };
                        itemParam.pokemonParam = UIManager.ToPokemonParam(itemParam.battle.battlePokemonParam);
                        pokemonPartyParam.itemParams.Add(itemParam);
                    }
                }

                // plate layout: which party slots show the player's own plate (0); the rest keep the default friend plate (1)
                Dpr.Battle.View.Systems.BattleViewSystem viewSystem = BattleViewCore.Instance.ViewSystem;
                MainModule mainModule = viewSystem.GetMainModule();
                BtlMultiMode multiMode = mainModule.GetMultiMode();
                int plateLayout;
                if (mainModule.IsScenarioMultiBattle())
                {
                    plateLayout = 0;
                }
                else
                {
                    switch (multiMode)
                    {
                        case BtlMultiMode.BTL_MULTIMODE_NONE:
                            switch (viewSystem.GetBattleRule())
                            {
                                case BtlRule.BTL_RULE_DOUBLE:
                                    plateLayout = 1;
                                    break;
                                case BtlRule.BTL_RULE_SAFARI:
                                    plateLayout = 3;
                                    break;
                                default:
                                    plateLayout = 0;
                                    break;
                            }
                            break;
                        case BtlMultiMode.BTL_MULTIMODE_P_AA:
                            plateLayout = 1;
                            break;
                        case BtlMultiMode.BTL_MULTIMODE_PP_PP:
                        case BtlMultiMode.BTL_MULTIMODE_PP_AA:
                        case BtlMultiMode.BTL_MULTIMODE_PA_AA:
                        case BtlMultiMode.BTL_MULTIMODE_PA_A:
                        case BtlMultiMode.BTL_MULTIMODE_PA_A2:
                            plateLayout = 2;
                            break;
                        default:
                            plateLayout = 0;
                            break;
                    }
                }

                for (int i = 0; i < pokemonPartyParam.itemParams.Count; i++)
                {
                    switch (plateLayout)
                    {
                        case 0:
                            if (i == 0)
                                pokemonPartyParam.itemParams[i].battle.plateType = 0;
                            break;
                        case 1:
                            if (i == 0 || i == 1)
                                pokemonPartyParam.itemParams[i].battle.plateType = 0;
                            break;
                        case 2:
                            if (i == 0 || i == 3)
                                pokemonPartyParam.itemParams[i].battle.plateType = 0;
                            break;
                        default:
                            pokemonPartyParam.itemParams[i].battle.plateType = 1;
                            break;
                    }
                }
            }
            else if (onlyViewPokemonParam != null)
            {
                var itemParam = new PokemonPartyItem.Param() { showItemName = false, pokemonParam = onlyViewPokemonParam };
                pokemonPartyParam.itemParams.Add(itemParam);
                onlyViewPartyIndex = (int)PlayerWork.playerParty.GetMemberIndex(onlyViewPokemonParam);
            }
            else
            {
                uint memberCount = PlayerWork.playerParty.GetMemberCount();
                for (int i = 0; i < memberCount; i++)
                {
                    PokemonParam pokemonParam = PlayerWork.playerParty.GetMemberPointerConst((uint)i);
                    var itemParam = new PokemonPartyItem.Param() { showItemName = false, pokemonParam = pokemonParam };
                    pokemonPartyParam.itemParams.Add(itemParam);
                }
            }
        }
		private void StartSelectPokemonParty(global::UnityEngine.Events.UnityAction<global::Dpr.UI.PokemonPartyItem, int> onClicked) {
            pokemonParty.SetActive(true, true);
            pokemonParty.onClicked = onClicked;
            pokemonParty.onClicked += (_, __) => AudioManager.Instance.PlaySe(AK.EVENTS.UI_COMMON_DECIDE, null);
            isWaitPokemonParty = true;
            UpdateKeyGuide();
        }
		private void EndSelectPokemonParty() {
            pokemonParty.SetActive(false, true);
            bagItemPanel.SetActive(true);
            pokemonParty.onClicked = null;
            isWaitPokemonParty = false;
            msgWindowController.CloseMsgWindow();
            UpdateKeyGuide();
        }
		private void OpenContextMenu(global::ContextMenuID[] contextMenuIDs, global::System.Action<global::ContextMenuID> onSelected, global::UnityEngine.Vector2 pivot, global::UnityEngine.Vector3 pos, global::System.Action onClosed = null, bool isNoDecideSe = false, bool isNoCancelSe = false) {
            var param = new ContextMenuWindow.Param();
            param.itemParams = new ContextMenuItem.Param[contextMenuIDs.Length];
            for (int i = 0; i < contextMenuIDs.Length; i++)
                param.itemParams[i] = new ContextMenuItem.Param() { menuId = contextMenuIDs[i] };

            param.pivot = pivot;
            param.position = pos;
            param.minItemWidth = 122f;
            param.useLoopAndRepeat = false;
            param.isInputEnable = !isAutoPilot;
            if (isNoDecideSe)
                param.seDecide = 0;
            if (isNoCancelSe)
                param.seCancel = 0;

            ContextMenuWindow contextMenu = UIManager.Instance.CreateUIWindow<ContextMenuWindow>(UIWindowID.CONTEXTMENU);
            contextMenu.onClosed = _ => onClosed?.Invoke();
            contextMenu.onClicked = item =>
            {
                onSelected?.Invoke(item.param.menuId);
                return true;
            };
            contextMenu.Open(param);
        }
		private void ShowItemContextMenu(global::Dpr.Item.ItemInfo item) {
            if (item == null)
                return;

            var contextMenuIDs = new System.Collections.Generic.List<ContextMenuID>();
            Action useItemAction = null;
            Action equipItemAction = null;

            if (modeType != ModeType.EquipOnly)
            {
                if (!isDontBuryNuts && isKinomiContact && item.IsNuts)
                {
                    contextMenuIDs.Add(ContextMenuID.BAG_ITEM_BURY_NUTS);
                }
                else if (item.CheckAllowUse(isBattle))
                {
                    if (isBattle)
                    {
                        if (battleBootParam.IsTrainerBattle && (item.Id == (int)ItemNo.PIPPININGYOU || item.Id == (int)ItemNo.ENEKONOSIPPO))
                        {
                            // Poke Doll / Fluffy Tail in a trainer battle: "can't use it now" message only
                            contextMenuIDs.Add(ContextMenuID.BAG_ITEM_USE);
                            useItemAction = () =>
                            {
                                Dpr.Message.MessageWordSetHelper.SetPlayerNickNameWord(0);
                                msgWindowController.OpenMsgWindow(UIMsgWindowController.MessageFileType.Bag, DontUseItemDoctorsAdviceMessageLabel, true, false, null, EndUseAction);
                            };
                        }
                        else if (onlyViewPokemonParam != null)
                        {
                            contextMenuIDs.Add(ContextMenuID.BAG_ITEM_USE);
                            useItemAction = () => OnBattleBootPokemonPartyClickedToUseItem(pokemonParty.GetSelectedItem(), 0);
                        }
                        else if (item.IsCategory(ItemInfo.CategoryType.Ball))
                        {
                            contextMenuIDs.Add(ContextMenuID.BAG_ITEM_USE);
                            useItemAction = () =>
                            {
                                UIManager.onUseItemInBattle?.Invoke(-1, -1, item);
                                Close(onClosed, _prevWindowId, true);
                            };
                        }
                        else if (item.IsCategory(ItemInfo.CategoryType.Battle))
                        {
                            contextMenuIDs.Add(ContextMenuID.BAG_ITEM_USE);
                            if (battleBootParam.isDouble)
                            {
                                useItemAction = () =>
                                {
                                    msgWindowController.OpenMsgWindow(UIMsgWindowController.MessageFileType.Bag, QuestionWhichUseItemMessageLabel, false, false, null, null);
                                    StartSelectPokemonParty(OnBattleBootPokemonPartyClickedToUseItem);
                                };
                            }
                            else
                            {
                                useItemAction = () =>
                                {
                                    UIManager.onUseItemInBattle?.Invoke(-1, -1, item);
                                    Close(onClosed, _prevWindowId, true);
                                };
                            }
                        }
                        else
                        {
                            contextMenuIDs.Add(ContextMenuID.BAG_ITEM_USE);
                            useItemAction = () =>
                            {
                                msgWindowController.OpenMsgWindow(UIMsgWindowController.MessageFileType.Bag, QuestionWhichUseItemMessageLabel, false, false, null, null);
                                StartSelectPokemonParty(OnBattleBootPokemonPartyClickedToUseItem);
                            };
                        }
                    }
                    else if (!item.IsCategory(ItemInfo.CategoryType.Ball))
                    {
                        if (onlyViewPokemonParam != null)
                        {
                            contextMenuIDs.Add(ContextMenuID.BAG_ITEM_USE);
                            useItemAction = () => OnPokemonPartyClickedToUseItem(pokemonParty.GetSelectedItem(), onlyViewPartyIndex);
                        }
                        else
                        {
                            ItemData.FieldFunctionType fieldFuncType = item.GetFieldFunctionType();
                            if (fieldFuncType == ItemData.FieldFunctionType.ITEMUSE_FLD_POFINKEESU)
                            {
                                if (!IsOpenFromBattleTeam)
                                    contextMenuIDs.Add(ContextMenuID.BAG_ITEM_OPEN_POFFIN_CASE);
                            }
                            else if (fieldFuncType == ItemData.FieldFunctionType.ITEMUSE_FLD_CYCLE)
                            {
                                if (!IsOpenFromBattleTeam)
                                    contextMenuIDs.Add(PlayerWork.IsFormBicycle() ? ContextMenuID.BAG_ITEM_GET_OFF_BICYCLE : ContextMenuID.BAG_ITEM_USE);
                            }
                            else
                            {
                                contextMenuIDs.Add(ContextMenuID.BAG_ITEM_USE);
                            }

                            useItemAction = () =>
                            {
                                switch (fieldFuncType)
                                {
                                    case ItemData.FieldFunctionType.ITEMUSE_FLD_RECOVER:
                                    case ItemData.FieldFunctionType.ITEMUSE_FLD_WAZA:
                                    case ItemData.FieldFunctionType.ITEMUSE_FLD_EVOLUTION:
                                    case ItemData.FieldFunctionType.ITEMUSE_FLD_APPLICATION:
                                    case ItemData.FieldFunctionType.ITEMUSE_FLD_KINOMI:
                                    case ItemData.FieldFunctionType.ITEMUSE_FLD_FORM_CHANGE:
                                        if (item.IsRecoveryAllDead)
                                        {
                                            float recoverHpRate = GetRecoverHpRate((ItemData.HpRecoverType)item.RecoveryHpValue);
                                            var recoverPokemonItems = new System.Collections.Generic.List<PokemonPartyItem>();
                                            for (int i = 0; i < pokemonParty.items.Count; i++)
                                            {
                                                PokemonParam pokemonParam = pokemonParty.items[i].param.pokemonParam;
                                                if (pokemonParam.IsHpZero())
                                                {
                                                    pokemonParam.RecoverHp(pokemonParam.GetMaxHp() == 1 ? 1 : (uint)(recoverHpRate * pokemonParam.GetMaxHp()));
                                                    recoverPokemonItems.Add(pokemonParty.items[i]);
                                                    FieldManager.fwMng.CreateTurearuki();
                                                }
                                            }

                                            if (recoverPokemonItems.Count != 0)
                                            {
                                                int itemIndex = 0;
                                                UpdateHp();
                                                return;

                                                void UpdateHp()
                                                {
                                                    AudioManager.Instance.PlaySe(AK.EVENTS.UI_BAG_ITEM_RECOVERY, null);
                                                    recoverPokemonItems[itemIndex].UpdateHp(() =>
                                                    {
                                                        recoverPokemonItems[itemIndex].Setup(recoverPokemonItems[itemIndex].param);
                                                        Dpr.Message.MessageWordSetHelper.SetPokemonNickNameWord(0, recoverPokemonItems[itemIndex].param.pokemonParam, true);
                                                        msgWindowController.OpenMsgWindow(UIMsgWindowController.MessageFileType.Bag, RecoveryDeadResultMessageLabel, true, false, null, () =>
                                                        {
                                                            if (++itemIndex < recoverPokemonItems.Count)
                                                                UpdateHp();
                                                            else
                                                                EndUseItemAction(null, item, 1, true);
                                                        });
                                                    });
                                                }
                                            }

                                            msgWindowController.OpenMsgWindow(UIMsgWindowController.MessageFileType.Bag, NoEffectUseItemResultMessageLabel, true, false, null, EndUseAction);
                                        }
                                        else
                                        {
                                            msgWindowController.OpenMsgWindow(UIMsgWindowController.MessageFileType.Bag, QuestionWhichUseItemMessageLabel, false, false, null, null);
                                            StartSelectPokemonParty(OnPokemonPartyClickedToUseItem);
                                        }
                                        return;

                                    case ItemData.FieldFunctionType.ITEMUSE_FLD_BAG_MSG:
                                    {
                                        ushort itemNo = (ushort)item.Id;
                                        if ((itemNo == (ushort)ItemNo.SIRUBAASUPUREE || itemNo == (ushort)ItemNo.GOORUDOSUPUREE || itemNo == (ushort)ItemNo.MUSIYOKESUPUREE) && !ZoneWork.IsUnderGround(PlayerWork.zoneID))
                                        {
                                            if (ItemWork.IsUseSpray(out ItemNo usingSpray))
                                            {
                                                msgWindowController.OpenMsgWindow(UIMsgWindowController.MessageFileType.Bag, DontUseSprayItemMessageLabel, true, false, null, EndUseAction);
                                            }
                                            else
                                            {
                                                ItemWork.SetSpray((ItemNo)itemNo, (short)(item.GetParam(ItemData.PrmID.ATTACK) * 5));
                                                ItemWork.SubItem(item.Id, 1);
                                                AudioManager.Instance.PlaySe(AK.EVENTS.UI_BAG_ITEM_INSECT_REPELLENT, null);
                                                Dpr.Message.MessageWordSetHelper.SetPlayerNickNameWord(0);
                                                Dpr.Message.MessageWordSetHelper.SetItemWord(1, item.Id, 1);
                                                msgWindowController.OpenMsgWindow(UIMsgWindowController.MessageFileType.Bag, UsedItemMessageLabel, true, false, null, () =>
                                                {
                                                    bagItemPanel.ReloadItemList(false, 0);
                                                    bagItemPanel.SetActive(true);
                                                });
                                            }
                                            return;
                                        }
                                        break;
                                    }

                                    case ItemData.FieldFunctionType.ITEMUSE_FLD_BOUKENNOOTO:
                                        Close(null, UIWindowID.ADVENTURE_NOTE, true);
                                        Sequencer.Start(FadeTransition<AdventureNoteWindow>(TransitionFadeFillColor, 0f, () =>
                                        {
                                            AdventureNoteWindow window = UIManager.Instance.CreateUIWindow<AdventureNoteWindow>(UIWindowID.ADVENTURE_NOTE);
                                            window.onClosed += _ =>
                                            {
                                                UIBag bag = UIManager.Instance.CreateUIWindow<UIBag>(UIWindowID.BAG);
                                                bag.onPreClose = onPreClose;
                                                bag.onClosed = onClosed;
                                                bag.Open(bootType, modeType, onlyViewPokemonParam, displayMoney, false, window.instance.windowId);
                                                bag._prevWindowId = _prevWindowId;
                                            };
                                            window.Open(instance.windowId);
                                        }));
                                        return;

                                    case ItemData.FieldFunctionType.ITEMUSE_FLD_POFINKEESU:
                                    {
                                        UnityAction<UIWindow> saveOnPreClose;
                                        UnityAction<UIWindow> saveOnClosed;
                                        saveOnClosed = onClosed;
                                        saveOnPreClose = onPreClose;
                                        onPreClose = null;
                                        Close(_ =>
                                        {
                                            UIPofinCase window = UIManager.Instance.CreateUIWindow<UIPofinCase>(UIWindowID.POFIN_CASE);
                                            window.onClosed += __ =>
                                            {
                                                UIBag bag = UIManager.Instance.CreateUIWindow<UIBag>(UIWindowID.BAG);
                                                bag.onPreClose = saveOnPreClose;
                                                bag.onClosed = saveOnClosed;
                                                bag.Open(bootType, modeType, onlyViewPokemonParam, displayMoney, false, window.instance.windowId);
                                                bag._prevWindowId = _prevWindowId;
                                            };
                                            window.Open(instance.windowId);
                                        }, UIWindowID.POFIN_CASE, true);
                                        return;
                                    }

                                    case ItemData.FieldFunctionType.ITEMUSE_FLD_TENKAINOHUE:
                                        if (PlayerWork.zoneID == (ZoneID)0xd8 || PlayerWork.zoneID == (ZoneID)0xd9)
                                        {
                                            UIManager.Instance.CloseXMenu(onClosed_ =>
                                            {
                                                Close(onClosed_ + (_ =>
                                                {
                                                    Dpr.EvScript.EvDataManager.Instanse.Cmd_ObjPauseAll();
                                                    Dpr.EvScript.EvDataManager.Instanse.JumpLabel("pos_tenkainofue", null);
                                                }), WINDOWID_FIELD, true);
                                            });
                                            return;
                                        }
                                        Dpr.Message.MessageWordSetHelper.SetPlayerNickNameWord(0);
                                        msgWindowController.OpenMsgWindow(UIMsgWindowController.MessageFileType.Bag, DontUseItemMessageLabel, true, false, null, EndUseAction);
                                        return;

                                    case ItemData.FieldFunctionType.ITEMUSE_FLD_POINTOKAADO:
                                        Dpr.Message.MessageWordSetHelper.SetDigitWord(0, BtlTowerWork.GetBP());
                                        msgWindowController.OpenMsgWindow(UIMsgWindowController.MessageFileType.Bag, PointCardMessageLabel, true, false, null, EndUseAction);
                                        return;

                                    case ItemData.FieldFunctionType.ITEMUSE_FLD_DS_PLAYER:
                                        UIManager.Instance.UseDSPlayerItem();
                                        msgWindowController.OpenMsgWindow(UIMsgWindowController.MessageFileType.Bag, ItemWork.IsDsPlayer() ? DsPlayerOnMessageLabel : DsPlayerOffMessageLabel, true, false, null, EndUseAction);
                                        return;

                                    default:
                                        if (UIManager.onUseFieldItem != null)
                                        {
                                            UIManager.FieldUseResult fieldUseResult = UIManager.onUseFieldItem(item);
                                            if (fieldUseResult == UIManager.FieldUseResult.Unusable_PairTrainer)
                                            {
                                                FieldManager.fwMng.SetPartnerNameToLabel(0);
                                                msgWindowController.OpenMsgWindow("dp_scenario3", "DP_menu_msg2_2255_01", true, false, null, EndUseAction);
                                                return;
                                            }
                                            if (fieldUseResult == UIManager.FieldUseResult.Available)
                                            {
                                                if (!item.IsNoSpend)
                                                    ItemWork.SubItem(item.Id, 1);
                                                PlayerWork.UsedFieldItem = item;
                                                UIManager.Instance.CloseXMenu(onClosed_ => Close(onClosed_, WINDOWID_FIELD, true));
                                                return;
                                            }
                                        }
                                        if (fieldFuncType == ItemData.FieldFunctionType.ITEMUSE_FLD_CYCLE && PlayerWork.IsFormBicycle())
                                        {
                                            msgWindowController.OpenMsgWindow(UIMsgWindowController.MessageFileType.Bag, CantGetOffBicycleMessageLabel, true, false, null, EndUseAction);
                                            return;
                                        }
                                        break;
                                }

                                Dpr.Message.MessageWordSetHelper.SetPlayerNickNameWord(0);
                                msgWindowController.OpenMsgWindow(UIMsgWindowController.MessageFileType.Bag, DontUseItemMessageLabel, true, false, null, EndUseAction);
                            };
                        }
                    }
                }
            }

            if (item.IsAllowEquip && !isBattle && modeType != ModeType.Recovery)
            {
                contextMenuIDs.Add(ContextMenuID.BAG_ITEM_EQUIP);
                if (onlyViewPokemonParam != null)
                {
                    equipItemAction = () => OnPokemonPartyClickedToEquipItem(pokemonParty.GetSelectedItem(), 0);
                }
                else
                {
                    equipItemAction = () =>
                    {
                        msgWindowController.OpenMsgWindow(UIMsgWindowController.MessageFileType.Bag, QuestionWhichEquipItemMessageLabel, false, false, null, null);
                        StartSelectPokemonParty(OnPokemonPartyClickedToEquipItem);
                    };
                }
            }

            if (item.IsNuts && !isBattle && modeType != ModeType.Recovery && !IsOpenFromBattleTeam)
                contextMenuIDs.Add(ContextMenuID.BAG_ITEM_NUTSTAG);

            if (item.GetFieldFunctionType() == ItemData.FieldFunctionType.ITEMUSE_FLD_TANKENSETTO && !IsOpenFromBattleTeam)
                contextMenuIDs.Add(ContextMenuID.BAG_ITEM_VIEW_EXPLORERKIT);

            if (item.IsUseful && !IsOpenFromBattleTeam)
                contextMenuIDs.Add(item.IsRegisterShorcut ? ContextMenuID.BAG_ITEM_UNREGISTER : ContextMenuID.BAG_ITEM_REGISTER);

            contextMenuIDs.Add(ContextMenuID.BAG_ITEM_CANCEL);

            RectTransform rectTransform = bagItemPanel.SelectedItemButton.GetRectTransform();
            Vector2 pivot = new Vector2(1f, 0.5f);
            // two-argument Vector3 ctor (RVA 0x29A2D60, z = 0) @0185b198
#if !SWITCH
            // s40: half the button width (UI units) in world pixels (PcUiRoot.UnitScale; 1 at 720p) - the menu's left edge at the button's right edge
            Vector3 pos = new Vector3(rectTransform.position.x + rectTransform.sizeDelta.x * 0.5f * PcPlatform.PcUiRoot.UnitScale(rectTransform), rectTransform.position.y);
#else
            Vector3 pos = new Vector3(rectTransform.position.x + rectTransform.sizeDelta.x * 0.5f, rectTransform.position.y);
#endif
            OpenContextMenu(contextMenuIDs.ToArray(), OnSelected, pivot, pos, null, false, false);

            void EndUseAction()
            {
                bagItemPanel.SetActive(true);
            }

            void OnSelected(ContextMenuID menuID)
            {
                switch (menuID)
                {
                    case ContextMenuID.BAG_ITEM_USE:
                    case ContextMenuID.BAG_ITEM_GET_OFF_BICYCLE:
                    case ContextMenuID.BAG_ITEM_OPEN_POFFIN_CASE:
                        useItemAction?.Invoke();
                        break;

                    case ContextMenuID.BAG_ITEM_EQUIP:
                        equipItemAction?.Invoke();
                        break;

                    case ContextMenuID.BAG_ITEM_NUTSTAG:
                    {
                        UIKinomi window;
                        System.Collections.Generic.List<ItemInfo> itemInfoList = ItemWork.GetItemInfosByCategory(ItemInfo.CategoryType.Nuts);
                        window = UIManager.Instance.CreateUIWindow<UIKinomi>(UIWindowID.KINOMI);
                        window.onPreClose += _ =>
                        {
                            bagItemPanel.ReloadItemList(false, window.SelectedKinomiItemId);
                            bagItemPanel.SetActive(true);
                        };
                        window.Open(itemInfoList, bagItemPanel.SelectedItemButton.GetInfo(), _ => UpdateKeyGuide());
                        break;
                    }

                    case ContextMenuID.BAG_ITEM_REGISTER:
                    {
                        UIRegisterItemShortcut window = UIManager.Instance.CreateUIWindow<UIRegisterItemShortcut>(UIWindowID.REGISTER_ITEM_SHORTCUT);
                        window.onClosed += _ =>
                        {
                            bagItemPanel.ReloadItemList(false, 0);
                            bagItemPanel.SetActive(true);
                        };
                        window.OpenRegister((ushort)item.Id);
                        break;
                    }

                    case ContextMenuID.BAG_ITEM_UNREGISTER:
                        PlayerWork.SetItemShortcut(item.ShortcutId, 0);
                        bagItemPanel.ReloadItemList(false, 0);
                        bagItemPanel.SetActive(true);
                        break;

                    case ContextMenuID.BAG_ITEM_BURY_NUTS:
                        PlayerWork.UsedFieldItem = item;
                        UIManager.Instance.CloseXMenu(onClosed_ => Close(onClosed_, WINDOWID_FIELD, true));
                        break;

                    case ContextMenuID.BAG_ITEM_VIEW_EXPLORERKIT:
                    {
                        UnityAction<UIWindow> saveOnPreClose;
                        UnityAction<UIWindow> saveOnClosed;
                        saveOnClosed = onClosed;
                        saveOnPreClose = onPreClose;
                        onPreClose = null;
                        Close(_ =>
                        {
                            UIBagUG window = UIManager.Instance.CreateUIWindow<UIBagUG>(UIWindowID.BAG_UG);
                            window.onClosed += __ =>
                            {
                                UIBag bag = UIManager.Instance.CreateUIWindow<UIBag>(UIWindowID.BAG);
                                bag.onPreClose = saveOnPreClose;
                                bag.onClosed = saveOnClosed;
                                bag.Open(bootType, modeType, onlyViewPokemonParam, displayMoney, false, window.instance.windowId);
                                bag._prevWindowId = _prevWindowId;
                            };
                            window.Open(instance.windowId);
                        }, UIWindowID.BAG_UG, true);
                        break;
                    }

                    default:
                        bagItemPanel.SetActive(true);
                        break;
                }
            }
        }
		private void SwitchSelectedItemFavorite() {
            if (bagItemPanel.SelectedItemButton == null)
                return;

            bagItemPanel.SelectedItemButton.SwitchFavorite();
            AudioManager.Instance.PlaySe(AK.EVENTS.UI_COMMON_DECIDE, null);
        }
		private void ShowWazaOboeWindow(global::Pml.PokePara.PokemonParam pokemonParam, global::Pml.WazaNo learnWazaNo, global::System.Action<global::Pml.WazaNo, global::Pml.WazaNo> resultCallBack) {
            Dpr.Message.MessageWordSetHelper.SetWazaNameWord(0, learnWazaNo);
