		private void StartSortItems() {
            bagItemPanel.SetRemoveNewEnable(false);
            msgWindowController.OpenMsgWindow(UIMsgWindowController.MessageFileType.Bag, "SS_bag_083", true, false, () =>
            {
                var contextMenuIDs = new System.Collections.Generic.List<ContextMenuID>();
                contextMenuIDs.Add(bagItemPanel.CurrentCategoryId == (int)ItemInfo.CategoryType.WazaMachine ? ContextMenuID.BAG_SORT_NUMBER : ContextMenuID.BAG_SORT_TYPE);
                contextMenuIDs.Add(ContextMenuID.BAG_SORT_NAME);
                if (ItemWork.IsIncludeNewItem(bagItemPanel.CurrentCategoryId))
                    contextMenuIDs.Add(ContextMenuID.BAG_SORT_NEW);
                if (ItemWork.IsIncludeFavoriteItem(bagItemPanel.CurrentCategoryId))
                    contextMenuIDs.Add(ContextMenuID.BAG_SORT_FAVORITE);
                contextMenuIDs.Add(ContextMenuID.BAG_SORT_CANCEL);

                Vector2 pos = Dpr.MsgWindow.MsgWindowManager.Instance.MsgWindow.CalcContextMenuPos();
                Vector2 pivot = new Vector2(1f, 0f);
                AudioManager.Instance.PlaySe(AK.EVENTS.UI_COMMON_DECIDE, null);
                OpenContextMenu(contextMenuIDs.ToArray(), OnSelected, pivot, pos, null, true, true);
            }, null);

            void OnSelected(ContextMenuID contextMenuID)
            {
                switch (contextMenuID)
                {
                    case ContextMenuID.BAG_SORT_TYPE:
                    case ContextMenuID.BAG_SORT_NUMBER:
                        SortItems(ItemInfo.SortType.Type);
                        return;
                    case ContextMenuID.BAG_SORT_NAME:
                        SortItems(ItemInfo.SortType.Name);
                        return;
                    case ContextMenuID.BAG_SORT_NEW:
                        SortItems(ItemInfo.SortType.New);
                        return;
                    case ContextMenuID.BAG_SORT_FAVORITE:
                        SortItems(ItemInfo.SortType.Favorite);
                        return;
                    default:
                        msgWindowController.CloseMsgWindow();
                        bagItemPanel.SetRemoveNewEnable(true);
                        AudioManager.Instance.PlaySe(AK.EVENTS.UI_COMMON_MENU_CLOSE, null);
                        return;
                }
            }
        }
		private void SortItems(global::Dpr.Item.ItemInfo.SortType sortType) {
            ItemWork.SortItemInfosByCategory(bagItemPanel.CurrentCategoryId, sortType);
            bagItemPanel.ReloadItemList(false, 0);
            ShowSortResultMessage(sortType);
            AudioManager.Instance.PlaySe(AK.EVENTS.UI_BAG_SORT_DONE, null);
        }
		private void ShowSortResultMessage(global::Dpr.Item.ItemInfo.SortType sortType) {
            string labelName;
            switch (sortType)
            {
                case ItemInfo.SortType.Type:
                    labelName = bagItemPanel.CurrentCategoryId == (int)ItemInfo.CategoryType.WazaMachine ? NumberSortResultMessageLabel : TypeSortResultMessageLabel;
                    break;
                case ItemInfo.SortType.Name:
                    labelName = NameSortResultMessageLabel;
                    break;
                case ItemInfo.SortType.New:
                    labelName = NewSortResultMessageLabel;
                    break;
                case ItemInfo.SortType.Favorite:
                    labelName = FavoriteSortResultMessageLabel;
                    break;
                default:
                    labelName = null;
                    break;
            }
            msgWindowController.OpenMsgWindow(UIMsgWindowController.MessageFileType.Bag, labelName, true, false, null, () => bagItemPanel.SetRemoveNewEnable(true));
        }
		private void OnPokemonPartyClickedToUseItem(global::Dpr.UI.PokemonPartyItem pokemonPartyItem, int index) {
            ItemInfo itemInfo;
            PokemonParam pokeParam = pokemonPartyItem.param.pokemonParam;
            if (pokeParam.IsEgg(EggCheckType.BOTH_EGG))
            {
                msgWindowController.OpenMsgWindow(UIMsgWindowController.MessageFileType.Bag, NoEffectUseItemResultMessageLabel, true, false, null, GetUseItemToNothingAction());
                return;
            }

            itemInfo = bagItemPanel.SelectedItemButton.GetInfo();
            switch (itemInfo.GetFieldFunctionType())
            {
                case ItemData.FieldFunctionType.ITEMUSE_FLD_RECOVER:
                case ItemData.FieldFunctionType.ITEMUSE_FLD_KINOMI:
                {
                    Seikaku seikaku;
                    PowerID powerID;
                    int addExpValue;
                    uint beforeHp;

                    if (itemInfo.IsLevelUp)
                    {
                        // Rare Candy
                        EvolveDemoTools.Param evolveParam;
                        int remainLevel = 100 - (int)pokeParam.GetLevel();
                        evolveParam = new EvolveDemoTools.Param() { pp = pokeParam, party = PlayerWork.playerParty, situation = new EvolveSituation() };
                        poketool.poketool_evolution_util.SetupEvolveSituation(evolveParam.situation, false, PlayerWork.FieldWeather);
                        MonsNo nextMonsNo = 0;
                        uint rootNum = 0;
                        if (remainLevel == 0 && !pokeParam.CanEvolve(evolveParam.situation, evolveParam.party, ref nextMonsNo, ref rootNum))
                            break;

                        if (itemInfo.count == 1)
                        {
                            DecideAction(itemInfo.count);
                            return;
                        }

                        int maxAmount = remainLevel == 0 ? 1 : Mathf.Min(itemInfo.count, remainLevel);
                        bagItemPanel.ShowSelectAmount(1, maxAmount, DecideAction, GetUseItemToNothingAction(), null);
                        Dpr.Message.MessageWordSetHelper.SetItemWord(1, itemInfo.Id, 1);
                        msgWindowController.OpenMsgWindow(UIMsgWindowController.MessageFileType.Bag, QuestionHowManyUseItemMessageLabel, false, false, null, null);
                        return;

                        void DecideAction(int amount)
                        {
                            UILevelUp levelUpWindow = UIManager.Instance.CreateUIWindow<UILevelUp>(UIWindowID.LEVEL_UP);
                            levelUpWindow.onClosed = _ =>
                            {
                                if (EvolveDemoTools.DoEvolve(evolveParam, EvolveResult))
                                {
                                    isWaitUpdate = true;
                                }
                                else
                                {
                                    EndUseItemAction(pokeParam, itemInfo, amount, false);
                                    pokemonPartyItem.Setup(pokemonPartyItem.param);
                                }
                                FieldManager.fwMng.CreateTurearuki();
                            };
                            levelUpWindow.Open(new UILevelUp.Param() { TargetIndex = index, LevelUpCount = amount }, WINDOWID_PARENT);

                            void EvolveResult(Demo_Evolve.Result result)
                            {
                                EndUseItemAction(pokeParam, itemInfo, amount, false);
                                CreatePokemonPartyParam(index);
                                pokemonParty.Setup(pokemonPartyParam);
                                isWaitUpdate = false;
                            }
                        }
                    }

                    if (itemInfo.GetSeikaku(out seikaku))
                    {
                        // nature mint
                        Dpr.Message.MessageWordSetHelper.SetPokemonNickNameWord(0, pokeParam, true);
                        msgWindowController.OpenMsgWindow(UIMsgWindowController.MessageFileType.Bag, QuestionUseMintItemMessageLabel, true, false, () =>
                        {
                            Dpr.MsgWindow.MsgWindowManager.OpenYesNoMenu(index2 =>
                            {
                                msgWindowController.CloseMsgWindow();
                                if (index2 != 0)
                                {
                                    GetUseItemToNothingAction()();
                                    return;
                                }

                                if (seikaku != Seikaku.MAJIME || itemInfo.IsUsableMajimeMint(pokeParam.GetSeikakuHosei()))
                                {
                                    if (pokeParam.GetSeikakuHosei() != seikaku)
                                    {
                                        EndSelectPokemonParty();
                                        pokeParam.ChangeSeikakuHosei(seikaku);
                                        PlayerWork.playReportDataRef.personal_change++;
                                        Dpr.Message.MessageWordSetHelper.SetItemWord(0, itemInfo.Id, 1);
                                        Dpr.Message.MessageWordSetHelper.SetPokemonNickNameWord(1, pokeParam, true);
                                        msgWindowController.OpenMsgWindow(UIMsgWindowController.MessageFileType.Bag, UseMintItemResultMessageLabel, true, false, null, () => EndUseItemAction(pokeParam, itemInfo, 1, false));
                                        return;
                                    }
                                }
                                msgWindowController.OpenMsgWindow(UIMsgWindowController.MessageFileType.Bag, NoEffectUseItemResultMessageLabel, true, false, null, GetUseItemToNothingAction());
                            }, ContextMenuWindow.CursorType.Arrow, true, true, null, AK.EVENTS.UI_COMMON_DECIDE);
                        }, null);
                        return;
                    }

                    if (itemInfo.IsRecoveryPp)
                    {
                        wazaSelectPanel.Setup(pokeParam, index2 =>
                        {
                            byte wazaIndex = (byte)index2;
                            if (pokeParam.GetWazaPP(wazaIndex) == pokeParam.GetWazaMaxPP(wazaIndex))
                            {
                                msgWindowController.OpenMsgWindow(UIMsgWindowController.MessageFileType.Bag, NoEffectUseItemResultMessageLabel, true, false, null, GetUseItemToNothingAction());
                                return;
                            }

                            byte recoverValue = (byte)itemInfo.RecoveryPpValue;
                            if (recoverValue == 127)
                                pokeParam.RecoverWazaPP(wazaIndex);
                            else
                                pokeParam.RecoverWazaPP(wazaIndex, recoverValue);
                            AudioManager.Instance.PlaySe(AK.EVENTS.UI_BAG_ITEM_RECOVERY, null);
                            msgWindowController.OpenMsgWindow(UIMsgWindowController.MessageFileType.Bag, RecoverWazaPPResultMessageLabel, true, false, null, () => EndUseItemAction(pokeParam, itemInfo, 1, false));
                        }, GetUseItemToNothingAction());
                        wazaSelectPanel.Show();
                        msgWindowController.OpenMsgWindow(UIMsgWindowController.MessageFileType.Bag, QuestionRecoverWazaPPMessageLabel, false, true, null, null);
                        return;
                    }

                    if (itemInfo.IsRecoveryPpAll)
                    {
                        for (byte i = 0; i < pokeParam.GetWazaCount(); i++)
                        {
                            if (pokeParam.GetWazaPP(i) < pokeParam.GetWazaMaxPP(i))
                            {
                                byte recoverValue = (byte)itemInfo.RecoveryPpValue;
                                if (recoverValue == 127)
                                {
                                    pokeParam.RecoverWazaPPAll();
                                }
                                else
                                {
                                    for (byte j = 0; j < pokeParam.GetWazaCount(); j++)
                                        pokeParam.RecoverWazaPP(j, recoverValue);
                                }
                                AudioManager.Instance.PlaySe(AK.EVENTS.UI_BAG_ITEM_RECOVERY, null);
                                msgWindowController.OpenMsgWindow(UIMsgWindowController.MessageFileType.Bag, RecoverWazaPPResultMessageLabel, true, false, null, () => EndUseItemAction(pokeParam, itemInfo, 1, false));
                                return;
                            }
                        }
                        break;
                    }

                    if (itemInfo.IsPpUp || itemInfo.IsPp3Up)
                    {
                        wazaSelectPanel.Setup(pokeParam, index2 =>
                        {
                            byte wazaIndex = (byte)index2;
                            uint maxPP = pokeParam.GetWazaMaxPP(wazaIndex);
                            bool canUsePointUp = pokeParam.CanUsePointUp(wazaIndex);
                            if (maxPP < 5 || !canUsePointUp)
                            {
                                msgWindowController.OpenMsgWindow(UIMsgWindowController.MessageFileType.Bag, NoEffectUseItemResultMessageLabel, true, false, null, GetUseItemToNothingAction());
                                return;
                            }

                            uint beforeMaxPP = pokeParam.GetWazaMaxPP(wazaIndex);
                            if (itemInfo.IsPp3Up)
                                pokeParam.SetWazaPPUpCount(wazaIndex, 3);
                            else
                                pokeParam.IncWazaPPUpCount(wazaIndex);
                            uint afterMaxPP = pokeParam.GetWazaMaxPP(wazaIndex);
                            pokeParam.RecoverWazaPP(wazaIndex, (byte)(afterMaxPP - beforeMaxPP));
                            AudioManager.Instance.PlaySe(AK.EVENTS.UI_BAG_ITEM_RECOVERY, null);
                            Dpr.Message.MessageWordSetHelper.SetWazaNameWord(0, pokeParam.GetWazaNo(wazaIndex));
                            msgWindowController.OpenMsgWindow(UIMsgWindowController.MessageFileType.Bag, WazaPPUpResultMessageLabel, true, false, null, () => EndUseItemAction(pokeParam, itemInfo, 1, false));
                        }, GetUseItemToNothingAction());
                        wazaSelectPanel.Show();
                        msgWindowController.OpenMsgWindow(UIMsgWindowController.MessageFileType.Bag, QuestionWazaPPUpMessageLabel, false, true, null, null);
                        return;
                    }

                    if (CheckExpItem(itemInfo, out powerID, out addExpValue))
                    {
                        // EV / friendship berries and vitamins
                        if (powerID == PowerID.HP && addExpValue > 0 && pokeParam.GetMonsNo() == MonsNo.NUKENIN)
                            break;

                        bool isEffortPower = false;
                        int maxEffortUsableCount = 0;
                        int maxFriendshipUsableCount;
                        if (addExpValue < 0)
                        {
                            uint subValue = (uint)Mathf.Abs(addExpValue);
                            uint effortPower = pokeParam.GetEffortPower(powerID);
                            if (effortPower != 0)
                            {
                                maxEffortUsableCount = Mathf.CeilToInt((float)effortPower / subValue);
                                isEffortPower = true;
                            }
                        }
                        else
                        {
                            uint restEffortPower = 252 - pokeParam.GetEffortPower(powerID);
                            uint restTotalEffortPower = 510 - pokeParam.GetTotalEffortPower();
                            if (restEffortPower != 0 && restTotalEffortPower != 0)
                            {
                                maxEffortUsableCount = Mathf.CeilToInt(Mathf.Min(restEffortPower, restTotalEffortPower) / (float)addExpValue);
                                isEffortPower = true;
                            }
                        }

                        itemInfo.GetFriendshipValue(pokeParam.GetFriendship(), out int addFriendshipValue, out maxFriendshipUsableCount);
                        if (maxEffortUsableCount != 0 || (addExpValue <= 0 && maxFriendshipUsableCount != 0))
                        {
                            int maxCount = maxEffortUsableCount;
                            if (addExpValue < 0)
                                maxCount = Mathf.Max(maxEffortUsableCount, maxFriendshipUsableCount);
                            maxCount = Mathf.Min(itemInfo.count, maxCount);
                            bagItemPanel.ShowSelectAmount(1, maxCount, amount =>
                            {
                                uint changeValue;
                                if (!isEffortPower)
                                {
                                    changeValue = 0;
                                }
                                else
                                {
                                    uint beforeEffortPower = pokeParam.GetEffortPower(powerID);
                                    uint value = (uint)(amount * Mathf.Abs(addExpValue));
                                    if (addExpValue < 0)
                                        pokeParam.SubEffortPower(powerID, value);
                                    else
                                        pokeParam.AddEffortPower(powerID, value);
                                    changeValue = (uint)Mathf.Abs((int)(pokeParam.GetEffortPower(powerID) - beforeEffortPower));
                                }
                                AudioManager.Instance.PlaySe(AK.EVENTS.UI_BAG_ITEM_RECOVERY, null);

                                string labelName;
                                if (maxEffortUsableCount < 1)
                                    labelName = powerID == PowerID.HP ? AddFriendshipAndNotSubEffortPowerHPResultMessageLabel : AddFriendshipAndNotSubEffortPowerResultMessageLabel;
                                else if (addExpValue > 0)
                                    labelName = powerID == PowerID.HP ? AddEffortPowerHPResultMessageLabel : AddEffortPowerResultMessageLabel;
                                else if (maxFriendshipUsableCount > 0)
                                    labelName = powerID == PowerID.HP ? AddFriendshipAndSubEffortPowerHPResultMessageLabel : AddFriendshipAndSubEffortPowerResultMessageLabel;
                                else
                                    labelName = powerID == PowerID.HP ? NotAddFriendshipAndSubEffortPowerHPResultMessageLabel : NotAddFriendshipAndSubEffortPowerResultMessageLabel;

                                Dpr.Message.MessageWordSetHelper.SetPokemonNickNameWord(0, pokeParam, true);
                                Dpr.Message.MessageWordSetHelper.SetStatusNameWord(1, powerID, changeValue);
                                msgWindowController.OpenMsgWindow(UIMsgWindowController.MessageFileType.Bag, labelName, true, false, null, () =>
                                {
                                    EndUseItemAction(pokeParam, itemInfo, amount, false);
                                    pokemonPartyItem.Setup(pokemonPartyItem.param);
                                });
                            }, GetUseItemToNothingAction(), null);
                            Dpr.Message.MessageWordSetHelper.SetItemWord(1, itemInfo.Id, 1);
                            msgWindowController.OpenMsgWindow(UIMsgWindowController.MessageFileType.Bag, QuestionHowManyUseItemMessageLabel, false, false, null, null);
                            return;
                        }
                        break;
                    }

                    beforeHp = pokeParam.GetHp();
                    if (CheckAndUseRecoveryItem(pokeParam, itemInfo, true, out RecoveryResultType resultType))
                    {
                        string resultLabelName = GetRecoveryResultLabelName(resultType);
                        if (resultType != RecoveryResultType.None)
                            AudioManager.Instance.PlaySe(AK.EVENTS.UI_BAG_ITEM_RECOVERY, null);

                        if (resultType == RecoveryResultType.RecoveryHp || resultType == RecoveryResultType.RecoveryDead)
                        {
                            pokemonPartyItem.UpdateHp(() =>
                            {
                                isWaitUpdate = false;
                                pokemonPartyItem.Setup(pokemonPartyItem.param);
                                Dpr.Message.MessageWordSetHelper.SetPokemonNickNameWord(0, pokeParam, true);
                                Dpr.Message.MessageWordSetHelper.SetDigitWord(1, (int)(pokeParam.GetHp() - beforeHp));
                                msgWindowController.OpenMsgWindow(UIMsgWindowController.MessageFileType.Bag, resultLabelName, true, false, null, () => EndUseItemAction(pokeParam, itemInfo, 1, false));
                            });
                            isWaitUpdate = true;
                            return;
                        }

                        pokemonPartyItem.Setup(pokemonPartyItem.param);
                        Dpr.Message.MessageWordSetHelper.SetPokemonNickNameWord(0, pokeParam, true);
                        msgWindowController.OpenMsgWindow(UIMsgWindowController.MessageFileType.Bag, resultLabelName, true, false, null, () => EndUseItemAction(pokeParam, itemInfo, 1, false));
                        return;
                    }
                    break;
                }

                case ItemData.FieldFunctionType.ITEMUSE_FLD_WAZA:
                    UseWazaMachine(pokeParam, itemInfo);
                    return;

                case ItemData.FieldFunctionType.ITEMUSE_FLD_EVOLUTION:
                {
                    // evolution stones
                    EvolveSituation situation = new EvolveSituation();
                    poketool.poketool_evolution_util.SetupEvolveSituation(situation, false);
                    var param = new EvolveDemoTools.Param() { situation = situation, party = PlayerWork.playerParty, pp = pokeParam };
                    if (EvolveDemoTools.DoEvolve(param, OnResult, null, (ItemNo)itemInfo.Id))
                    {
                        isWaitUpdate = true;
                        msgWindowController.CloseMsgWindow();
                        return;
                    }
                    break;
                }

                case ItemData.FieldFunctionType.ITEMUSE_FLD_APPLICATION:
                    UseApplicationItem(pokeParam, itemInfo);
                    return;

                case ItemData.FieldFunctionType.ITEMUSE_FLD_FORM_CHANGE:
                    UseFormChangeItem(pokemonPartyItem, itemInfo);
                    return;
            }

            msgWindowController.OpenMsgWindow(UIMsgWindowController.MessageFileType.Bag, NoEffectUseItemResultMessageLabel, true, false, null, GetUseItemToNothingAction());

            void OnResult(Demo_Evolve.Result result)
            {
                isWaitUpdate = false;
                EndUseItemAction(pokeParam, itemInfo, 1, false);
                CreatePokemonPartyParam(index);
                pokemonParty.Setup(pokemonPartyParam);
            }
        }
		private void UseWazaMachine(global::Pml.PokePara.PokemonParam pokeParam, global::Dpr.Item.ItemInfo itemInfo) {
            ushort itemNo = (ushort)itemInfo.Id;
            uint machineNo = ItemData.GetWazaMashineNo(itemNo);
            WazaNo wazaNo = ItemData.GetWazaNo(itemNo);

            if (CanUseWazaMachine(pokeParam.GetMonsNo(), pokeParam.GetFormNo(), (ushort)machineNo))
            {
                if (pokeParam.HaveWaza(wazaNo))
                {
                    EndSelectPokemonParty();
                    Dpr.Message.MessageWordSetHelper.SetPokemonNickNameWord(0, pokeParam, true);
                    Dpr.Message.MessageWordSetHelper.SetWazaNameWord(1, wazaNo);
                    msgWindowController.OpenMsgWindow(UIMsgWindowController.MessageFileType.Bag, ResultExistWazaMessageLabel, true, false, null, null);
                }
                else
                {
                    msgWindowController.OpenMsgWindow(UIMsgWindowController.MessageFileType.Bag, QuestionUseWazaMachine1MessageLabel, true, false, null, () =>
                    {
                        msgWindowController.OpenMsgWindow(UIMsgWindowController.MessageFileType.Bag, QuestionUseWazaMachine2MessageLabel, true, false, null, () =>
                        {
                            msgWindowController.OpenMsgWindow(UIMsgWindowController.MessageFileType.Bag, QuestionUseWazaMachine3MessageLabel, true, false, () =>
                            {
                                Dpr.MsgWindow.MsgWindowManager.OpenYesNoMenu(index2 =>
                                {
                                    msgWindowController.CloseMsgWindow();
                                    if (index2 != 0)
                                    {
                                        GetUseItemToNothingAction()();
                                        return;
                                    }

                                    byte wazaIndex;
                                    for (wazaIndex = 0; wazaIndex < 4; wazaIndex++)
                                    {
                                        if (pokeParam.GetWazaNo(wazaIndex) == WazaNo.NULL)
                                            break;
                                    }
                                    if (wazaIndex == 4)
                                    {
                                        ShowWazaOboeWindow(pokeParam, wazaNo, (learnWazaNo, unlearnWazaNo) =>
                                        {
                                            if (learnWazaNo == WazaNo.NULL)
                                            {
                                                Dpr.Message.MessageWordSetHelper.SetPokemonNickNameWord(0, pokeParam, true);
                                                Dpr.Message.MessageWordSetHelper.SetWazaNameWord(1, wazaNo);
                                                msgWindowController.OpenMsgWindow(UIMsgWindowController.MessageFileType.Bag, ResultNotLearnWazaMessageLabel, true, false, null, EndSelectPokemonParty);
                                                return;
                                            }
                                            pokeParam.SetWaza(pokeParam.GetWazaIndex(unlearnWazaNo), learnWazaNo);
                                            PlayerWork.playReportDataRef.use_skill_record++;
                                            Dpr.Message.MessageWordSetHelper.SetPokemonNickNameWord(0, pokeParam, true);
                                            Dpr.Message.MessageWordSetHelper.SetWazaNameWord(1, unlearnWazaNo);
                                            Dpr.Message.MessageWordSetHelper.SetWazaNameWord(2, learnWazaNo);
                                            msgWindowController.OpenMsgWindow(UIMsgWindowController.MessageFileType.Bag, ResultUnlernToLearnWazaMessageLabel, true, false, null, () => EndUseItemAction(pokeParam, itemInfo, 1, true));
                                        });
                                        return;
                                    }

                                    pokeParam.SetWaza(wazaIndex, wazaNo);
                                    PlayerWork.playReportDataRef.use_skill_record++;
                                    Dpr.Message.MessageWordSetHelper.SetPokemonNickNameWord(0, pokeParam, true);
                                    Dpr.Message.MessageWordSetHelper.SetWazaNameWord(1, wazaNo);
                                    msgWindowController.OpenMsgWindow(UIMsgWindowController.MessageFileType.Bag, ResultLearnWazaMessageLabel, true, false, null, () => EndUseItemAction(pokeParam, itemInfo, 1, true));
                                }, ContextMenuWindow.CursorType.Arrow, true, true, null, AK.EVENTS.UI_COMMON_DECIDE);
                            }, null);
                        });
                    });
                }
            }
            else
            {
                Dpr.Message.MessageWordSetHelper.SetPokemonNickNameWord(0, pokeParam, true);
                Dpr.Message.MessageWordSetHelper.SetWazaNameWord(1, wazaNo);
                msgWindowController.OpenMsgWindow(UIMsgWindowController.MessageFileType.Bag, ResultCantLearnWazaMachineMessageLabel, true, false, null, GetUseItemToNothingAction());
            }
        }
		private void UseApplicationItem(global::Pml.PokePara.PokemonParam pokeParam, global::Dpr.Item.ItemInfo itemInfo) {
            switch ((ItemNo)(ushort)itemInfo.Id)
            {
                case ItemNo.TOKUSEIKAPUSERU:
                    UseTokuseiItem(pokeParam, itemInfo, pp =>
                    {
                        Pml.Personal.PersonalSystem.LoadPersonalData(pokeParam.GetMonsNo(), pokeParam.GetFormNo());
                        if (Pml.Personal.PersonalSystem.GetTokuseiPattern() == Pml.Personal.TokuseiPattern.ABC && pp.GetTokuseiIndex() != 2)
                        {
                            pp.FlipTokuseiIndex();
                            return true;
                        }
                        return false;
                    });
                    break;
                case ItemNo.TOKUSEIPATTI:
                    UseTokuseiItem(pokeParam, itemInfo, pp =>
                    {
                        Pml.Personal.PersonalSystem.LoadPersonalData(pokeParam.GetMonsNo(), pokeParam.GetFormNo());
                        if (Pml.Personal.PersonalSystem.GetTokuseiPattern() != Pml.Personal.TokuseiPattern.AAA && pp.GetTokuseiIndex() != 2)
                        {
                            pp.SetTokusei3rd();
                            return true;
                        }
                        return false;
                    });
                    break;
                default:
                    msgWindowController.OpenMsgWindow(UIMsgWindowController.MessageFileType.Bag, NoEffectUseItemResultMessageLabel, true, false, null, GetUseItemToNothingAction());
                    break;
            }
        }
		private void UseTokuseiItem(global::Pml.PokePara.PokemonParam pokeParam, global::Dpr.Item.ItemInfo itemInfo, global::System.Func<global::Pml.PokePara.PokemonParam, bool> useItemFunc) {
            Dpr.Message.MessageWordSetHelper.SetPokemonNickNameWord(0, pokeParam, true);
            msgWindowController.OpenMsgWindow(UIMsgWindowController.MessageFileType.Bag, QuestionUseTokuseiItemMessageLabel, true, false, () =>
            {
                Dpr.MsgWindow.MsgWindowManager.OpenYesNoMenu(index =>
                {
                    msgWindowController.CloseMsgWindow();
                    if (index == 0)
                    {
                        if (useItemFunc(pokeParam))
                        {
                            Dpr.Message.MessageWordSetHelper.SetPokemonNickNameWord(0, pokeParam, true);
                            Dpr.Message.MessageWordSetHelper.SetTokuseiWord(1, pokeParam.GetTokuseiNo());
                            msgWindowController.OpenMsgWindow(UIMsgWindowController.MessageFileType.Bag, UseTokuseiItemResultMessageLabel, true, false, null, () => EndUseItemAction(pokeParam, itemInfo, 1, false));
                        }
                        else
                        {
                            msgWindowController.OpenMsgWindow(UIMsgWindowController.MessageFileType.Bag, NoEffectUseItemResultMessageLabel, true, false, null, GetUseItemToNothingAction());
                        }
                        return;
                    }
                    GetUseItemToNothingAction()();
                }, ContextMenuWindow.CursorType.Arrow, true, true, null, AK.EVENTS.UI_COMMON_DECIDE);
            }, null);
        }
		private bool CheckAndUseRecoveryItem(global::Pml.PokePara.PokemonParam pokeParam, global::Dpr.Item.ItemInfo itemInfo, bool isUse, out global::Dpr.UI.UIBag.RecoveryResultType resultType) {
            resultType = RecoveryResultType.None;
            bool isRecovered = false;

            if (itemInfo.IsRecoveryPoison && RecoverySick(Sick.DOKU))
            {
                SetRecoverySickResult(ref resultType, RecoveryResultType.RecoveryPoison);
                isRecovered = true;
            }
            if (itemInfo.IsRecoveryBurn && RecoverySick(Sick.YAKEDO))
            {
                SetRecoverySickResult(ref resultType, RecoveryResultType.RecoveryBurn);
                isRecovered = true;
            }
            if (itemInfo.IsRecoveryIce && RecoverySick(Sick.KOORI))
            {
                SetRecoverySickResult(ref resultType, RecoveryResultType.RecoveryIce);
                isRecovered = true;
            }
            if (itemInfo.IsRecoveryParalyze && RecoverySick(Sick.MAHI))
            {
                SetRecoverySickResult(ref resultType, RecoveryResultType.RecoveryParalyze);
                isRecovered = true;
            }
            if (itemInfo.IsRecoverySleep && RecoverySick(Sick.NEMURI))
            {
                SetRecoverySickResult(ref resultType, RecoveryResultType.RecoverySleep);
                isRecovered = true;
            }

            if (isRecovered)
            {
                if (itemInfo.IsRecoveryPoison && itemInfo.IsRecoveryBurn && itemInfo.IsRecoveryIce && itemInfo.IsRecoveryParalyze && itemInfo.IsRecoverySleep)
                    resultType = RecoveryResultType.RecoveryAllSick;
                isRecovered = true;
            }

            if (itemInfo.IsRecoveryDead)
            {
                if (pokeParam.IsHpZero())
                {
                    resultType = RecoveryResultType.RecoveryDead;
                    if (isUse)
                    {
                        float recoverHpRate = GetRecoverHpRate((ItemData.HpRecoverType)itemInfo.RecoveryHpValue);
                        pokeParam.RecoverHp(pokeParam.GetMaxHp() == 1 ? 1 : (uint)(recoverHpRate * pokeParam.GetMaxHp()));
                        FieldManager.fwMng.CreateTurearuki();
                    }
                    isRecovered = true;
                }
            }
            else if (itemInfo.IsRecoveryHp && !pokeParam.IsHpFull() && !pokeParam.IsHpZero())
            {
                resultType = RecoveryResultType.RecoveryHp;
                if (isUse)
                {
                    uint recoverValue = (uint)itemInfo.RecoveryHpValue;
                    switch ((ItemData.HpRecoverType)recoverValue)
                    {
                        case ItemData.HpRecoverType.QUOT:
                            recoverValue = pokeParam.GetMaxHp() / 4;
                            break;
                        case ItemData.HpRecoverType.HALF:
                            recoverValue = pokeParam.GetMaxHp() / 2;
                            break;
                        case ItemData.HpRecoverType.FULL:
                            recoverValue = pokeParam.GetMaxHp();
                            break;
                    }
                    pokeParam.RecoverHp(recoverValue);
                }
                isRecovered = true;
            }

            return isRecovered;

            bool RecoverySick(Sick sick)
            {
                if (pokeParam.GetSick() == sick)
                {
                    if (isUse)
                        pokeParam.RecoverSick();
                    return true;
                }
                return false;
            }

            void SetRecoverySickResult(ref RecoveryResultType targetResultType, RecoveryResultType setResultType)
            {
                if (targetResultType != RecoveryResultType.None)
                    return;
                targetResultType = setResultType;
            }
        }
		private string GetRecoveryResultLabelName(global::Dpr.UI.UIBag.RecoveryResultType recoveryResult) {
            switch (recoveryResult)
            {
                case RecoveryResultType.RecoveryPoison:
                    return RecoveryPoisonResultMessageLabel;
                case RecoveryResultType.RecoveryBurn:
                    return RecoveryBurnResultMessageLabel;
                case RecoveryResultType.RecoveryIce:
                    return RecoveryIceResultMessageLabel;
                case RecoveryResultType.RecoveryParalyze:
                    return RecoveryParalyzeResultMessageLabel;
                case RecoveryResultType.RecoverySleep:
                    return RecoverySleepResultMessageLabel;
                case RecoveryResultType.RecoveryAllSick:
                    return RecoveryAllSickResultMessageLabel;
                case RecoveryResultType.RecoveryHp:
                    return RecoveryHpResultMessageLabel;
                case RecoveryResultType.RecoveryDead:
                    return RecoveryDeadResultMessageLabel;
                default:
                    return null;
            }
        }
		private float GetRecoverHpRate(global::Pml.Item.ItemData.HpRecoverType recoveryHpValue) {
            // value table @0x3d48880 = { 0.25f, 0.5f, 1f } indexed by recoveryHpValue - QUOT
            switch (recoveryHpValue)
            {
                case ItemData.HpRecoverType.QUOT:
                    return 0.25f;
                case ItemData.HpRecoverType.HALF:
                    return 0.5f;
                case ItemData.HpRecoverType.FULL:
                    return 1f;
                default:
                    return 0f;
            }
        }
		private bool CheckExpItem(global::Dpr.Item.ItemInfo itemInfo, out global::Pml.PokePara.PowerID powerID, out int addExpValue) {
            if (itemInfo.IsHpExp)
            {
                powerID = PowerID.HP;
                addExpValue = itemInfo.HpExpValue;
                return true;
            }
            if (itemInfo.IsAttackExp)
            {
                powerID = PowerID.ATK;
                addExpValue = itemInfo.AttackExpValue;
                return true;
            }
            if (itemInfo.IsDeffenceExp)
            {
                powerID = PowerID.DEF;
                addExpValue = itemInfo.DeffenceExpValue;
                return true;
            }
            if (itemInfo.IsSpAttackExp)
            {
                powerID = PowerID.SPATK;
                addExpValue = itemInfo.SpAttackExpValue;
                return true;
            }
            if (itemInfo.IsSpDeffenceExp)
            {
                powerID = PowerID.SPDEF;
                addExpValue = itemInfo.SpDeffenceExpValue;
                return true;
            }
            if (itemInfo.IsAgilityExp)
            {
                powerID = PowerID.AGI;
                addExpValue = itemInfo.AgilityExpValue;
                return true;
            }
            powerID = PowerID.NUM;
            addExpValue = 0;
            return false;
        }
		private global::System.Action GetUseItemToNothingAction() {
            // @0185d89c: `cmp onlyViewPokemonParam, #0 ; csel b__141_0 : EndSelectPokemonParty` feeding one Action ctor
            return onlyViewPokemonParam == null ? () =>
            {
                msgWindowController.OpenMsgWindow(UIMsgWindowController.MessageFileType.Bag, QuestionWhichUseItemMessageLabel, false, false, null, null);
                pokemonParty.SetActive(true, true);
            } : (Action)EndSelectPokemonParty;
        }
		private bool CanUseWazaMachine(global::Pml.MonsNo monsNo, ushort formNo, ushort machineNo) {
            Pml.Personal.PersonalSystem.LoadPersonalData(monsNo, formNo);
            return Pml.Personal.PersonalSystem.CheckPersonalWazaMachine(machineNo);
        }
		private void EndUseItemAction(global::Pml.PokePara.PokemonParam pokemonParam, global::Dpr.Item.ItemInfo itemInfo, int useCount = 1, bool isForceEnd = false) {
            ItemWork.SubItem(itemInfo.Id, useCount);
            if (pokemonParam != null)
            {
                if (itemInfo.IsKanpouyaku())
                    TvWork.Ryouyaku(pokemonParam, (ItemNo)itemInfo.Id);
                for (int i = 0; i < useCount; i++)
                    poketool.daisuki.poketool_daisuki.CalcWhenUseItem(pokemonParam, (ushort)itemInfo.Id);
            }

            bagItemPanel.ReloadItemList(false, 0);
            if (!isForceEnd && itemInfo.count > 0 && onlyViewPokemonParam == null)
            {
                msgWindowController.OpenMsgWindow(UIMsgWindowController.MessageFileType.Bag, QuestionWhichUseItemMessageLabel, false, false, null, null);
                StartSelectPokemonParty(OnPokemonPartyClickedToUseItem);
                return;
            }
            EndSelectPokemonParty();
        }
		private void UseFormChangeItem(global::Dpr.UI.PokemonPartyItem pokemonPartyItem, global::Dpr.Item.ItemInfo itemInfo) {
            PokemonParam pokemonParam = pokemonPartyItem.param.pokemonParam;
            switch (itemInfo.Id)
            {
                case (int)ItemNo.ROTOMUNOKATAROGU:
                {
                    if (pokemonParam.GetMonsNo() != MonsNo.ROTOMU)
                        break;

                    var contextMenuIDs = new System.Collections.Generic.List<ContextMenuID>();
                    contextMenuIDs.Add(ContextMenuID.BAG_ROTOM_FORMCHANGE_1);
                    if (FlagWork.GetFlag(Dpr.EvScript.EvWork.FLAG_INDEX.FE_ROTOMU_HOT))
                        contextMenuIDs.Add(ContextMenuID.BAG_ROTOM_FORMCHANGE_2);
                    if (FlagWork.GetFlag(Dpr.EvScript.EvWork.FLAG_INDEX.FE_ROTOMU_WASH))
                        contextMenuIDs.Add(ContextMenuID.BAG_ROTOM_FORMCHANGE_3);
                    if (FlagWork.GetFlag(Dpr.EvScript.EvWork.FLAG_INDEX.FE_ROTOMU_COLD))
                        contextMenuIDs.Add(ContextMenuID.BAG_ROTOM_FORMCHANGE_4);
                    if (FlagWork.GetFlag(Dpr.EvScript.EvWork.FLAG_INDEX.FE_ROTOMU_FAN))
                        contextMenuIDs.Add(ContextMenuID.BAG_ROTOM_FORMCHANGE_5);
                    if (FlagWork.GetFlag(Dpr.EvScript.EvWork.FLAG_INDEX.FE_ROTOMU_CUT))
                        contextMenuIDs.Add(ContextMenuID.BAG_ROTOM_FORMCHANGE_6);
                    contextMenuIDs.Add(ContextMenuID.BAG_ROTOM_FORMCHANGE_CANCEL);

                    OpenContextMenu(contextMenuIDs.ToArray(), selectContextMenuId =>
                    {
                        msgWindowController.CloseMsgWindow();
                        if (selectContextMenuId < ContextMenuID.BAG_ROTOM_FORMCHANGE_1 || selectContextMenuId > ContextMenuID.BAG_ROTOM_FORMCHANGE_6)
                        {
                            EndSelectPokemonParty();
                            return;
                        }

                        ushort formNo;
                        switch (selectContextMenuId)
                        {
                            case ContextMenuID.BAG_ROTOM_FORMCHANGE_1:
                                formNo = 0;
                                break;
                            case ContextMenuID.BAG_ROTOM_FORMCHANGE_3:
                                formNo = 2;
                                break;
                            case ContextMenuID.BAG_ROTOM_FORMCHANGE_4:
                                formNo = 3;
                                break;
                            case ContextMenuID.BAG_ROTOM_FORMCHANGE_5:
                                formNo = 4;
                                break;
                            case ContextMenuID.BAG_ROTOM_FORMCHANGE_6:
                                formNo = 5;
                                break;
                            default:
                                formNo = 1;
                                break;
                        }

                        if (formNo == pokemonParam.GetFormNo())
                        {
                            msgWindowController.OpenMsgWindow(UIMsgWindowController.MessageFileType.Bag, NoEffectUseItemResultMessageLabel, true, false, null, EndSelectPokemonParty);
                            return;
                        }

                        if (pokemonPartyItem.FormChange(formNo, effectRoot, null, ShowFormChangeResult))
                            isWaitUpdate = true;
                    }, new Vector2(0.5f, 0.5f), new Vector3(1040f, 360f, 0f), null, false, false);
                    msgWindowController.OpenMsgWindow(UIMsgWindowController.MessageFileType.Bag, QuestionRotomFormChangeMessageLabel, false, true, null, null);
                    return;
                }

                case (int)ItemNo.GURASIDEANOHANA:
                {
                    PeriodOfDay periodOfDay = GameManager.currentPeriodOfDay;
                    if (pokemonParam.GetMonsNo() == MonsNo.SHEIMI && pokemonParam.GetFormNo() == 0 &&
                        periodOfDay != PeriodOfDay.Night && periodOfDay != PeriodOfDay.Midnight && pokemonParam.GetSick() != Sick.KOORI)
                    {
                        if (pokemonPartyItem.FormChange(1, effectRoot, null, ShowFormChangeResult))
                            isWaitUpdate = true;
                        return;
                    }
                    break;
                }
            }

            msgWindowController.OpenMsgWindow(UIMsgWindowController.MessageFileType.Bag, NoEffectUseItemResultMessageLabel, true, false, null, EndSelectPokemonParty);
        }
		private void ShowFormChangeResult(global::Pml.PokePara.PokemonParam pokemonParam) {
            EndSelectPokemonParty();
            isWaitUpdate = false;
            Dpr.Message.MessageWordSetHelper.SetPokemonNickNameWord(0, pokemonParam, true);
            msgWindowController.OpenMsgWindow(UIMsgWindowController.MessageFileType.Bag, FormChangeResultMessageLabel, true, false, null, () =>
            {
                if (pokemonParam.GetMonsNo() != MonsNo.ROTOMU)
                    return;

                WazaNo[] beforeWazaNos = new WazaNo[pokemonParam.GetWazaCount()];
                for (byte i = 0; i < beforeWazaNos.Length; i++)
                    beforeWazaNos[i] = pokemonParam.GetWazaNo(i);

                pokemonParam.RemoveAllRotomWaza();
                pokemonParam.CloseUpWazaPos();

                if (beforeWazaNos.Length != pokemonParam.GetWazaCount())
                {
                    for (byte i = 0; i < beforeWazaNos.Length; i++)
                    {
                        if (pokemonParam.GetWazaIndex(beforeWazaNos[i]) == 4)
                        {
                            if (beforeWazaNos[i] != WazaNo.NULL)
                            {
                                Dpr.Message.MessageWordSetHelper.SetPokemonNickNameWord(0, pokemonParam, true);
                                Dpr.Message.MessageWordSetHelper.SetWazaNameWord(1, beforeWazaNos[i]);
                                msgWindowController.OpenMsgWindow(UIMsgWindowController.MessageFileType.Bag, ResultUnlearnWazaMessageLabel, true, false, null, AddWaza);
                                return;
                            }
                            break;
                        }
                    }
                }

                AddWaza();
            });

            void AddWaza()
            {
                if (pokemonParam.GetWazaCount() < 4)
                {
                    WazaNo beforeWazaNo = pokemonParam.GetWazaNo((byte)(pokemonParam.GetWazaCount() - 1));
                    pokemonParam.SetRotomWaza(0);
                    WazaNo afterWazaNo = pokemonParam.GetWazaNo((byte)(pokemonParam.GetWazaCount() - 1));
                    if (beforeWazaNo == afterWazaNo)
                        return;

                    Dpr.Message.MessageWordSetHelper.SetPokemonNickNameWord(0, pokemonParam, true);
                    Dpr.Message.MessageWordSetHelper.SetWazaNameWord(1, afterWazaNo);
                    msgWindowController.OpenMsgWindow(UIMsgWindowController.MessageFileType.Bag, ResultLearnWazaMessageLabel, true, false, null, null);
                }
                else
                {
                    WazaNo beforeWazaNo = pokemonParam.GetWazaNo(0);
                    pokemonParam.SetRotomWaza(0);
                    WazaNo addWazaNo = pokemonParam.GetWazaNo(0);
                    if (beforeWazaNo == addWazaNo)
                        return;

                    pokemonParam.SetWaza(0, beforeWazaNo);
                    Dpr.Message.MessageWordSetHelper.SetPokemonNickNameWord(0, pokemonParam, true);
                    Dpr.Message.MessageWordSetHelper.SetWazaNameWord(1, addWazaNo);
                    msgWindowController.OpenMsgWindow(UIMsgWindowController.MessageFileType.Bag, QuestionUnlernToLearnWazaMessageLabel, true, false, () =>
                    {
                        Dpr.MsgWindow.MsgWindowManager.OpenYesNoMenu(index =>
                        {
                            if (index != 0)
                            {
                                Dpr.Message.MessageWordSetHelper.SetPokemonNickNameWord(0, pokemonParam, true);
                                Dpr.Message.MessageWordSetHelper.SetWazaNameWord(1, addWazaNo);
                                msgWindowController.OpenMsgWindow(UIMsgWindowController.MessageFileType.Bag, ResultNotLearnWazaMessageLabel, true, false, null, null);
                                return;
                            }
                            ShowWazaOboeWindow(pokemonParam, addWazaNo, (learnWazaNo, unlearnWazaNo) =>
                            {
                                if (learnWazaNo == WazaNo.NULL)
                                {
                                    Dpr.Message.MessageWordSetHelper.SetPokemonNickNameWord(0, pokemonParam, true);
                                    Dpr.Message.MessageWordSetHelper.SetWazaNameWord(1, addWazaNo);
                                    msgWindowController.OpenMsgWindow(UIMsgWindowController.MessageFileType.Bag, ResultNotLearnWazaMessageLabel, true, false, null, null);
                                    return;
                                }
                                pokemonParam.SetWaza(pokemonParam.GetWazaIndex(unlearnWazaNo), learnWazaNo);
                                Dpr.Message.MessageWordSetHelper.SetPokemonNickNameWord(0, pokemonParam, true);
                                Dpr.Message.MessageWordSetHelper.SetWazaNameWord(1, unlearnWazaNo);
                                Dpr.Message.MessageWordSetHelper.SetWazaNameWord(2, learnWazaNo);
                                msgWindowController.OpenMsgWindow(UIMsgWindowController.MessageFileType.Bag, ResultUnlernToLearnWazaMessageLabel, true, false, null, null);
                            });
                        }, ContextMenuWindow.CursorType.Arrow, true, true, null, AK.EVENTS.UI_COMMON_DECIDE);
                    }, null);
                }
            }
        }
		private void OnBattleBootPokemonPartyClickedToUseItem(global::Dpr.UI.PokemonPartyItem pokemonPartyItem, int index) {
            ItemInfo itemInfo;
            PokemonParam pokeParam = pokemonPartyItem.param.pokemonParam;
            if (pokeParam.IsEgg(EggCheckType.BOTH_EGG))
            {
                msgWindowController.OpenMsgWindow(UIMsgWindowController.MessageFileType.Bag, NoEffectUseItemResultMessageLabel, true, false, null, GetUseItemToNothingAction());
                return;
            }

            if (battleBootParam.SasiosaeFlags[index])
            {
                // Embargo: "can't use items" message only
                Dpr.Message.MessageWordSetHelper.SetPokemonNickNameWord(0, pokeParam, true);
                msgWindowController.OpenMsgWindow(UIMsgWindowController.MessageFileType.Bag, DontUseItemMessageLabel, true, false, null, null);
                return;
            }

            itemInfo = bagItemPanel.SelectedItemButton.GetInfo();
            if (itemInfo.IsRecoveryPp)
            {
                wazaSelectPanel.Setup(pokeParam, index2 =>
                {
                    byte wazaIndex = (byte)index2;
                    UseItem(pokeParam.GetWazaPP(wazaIndex) != pokeParam.GetWazaMaxPP(wazaIndex), wazaIndex);
                }, GetUseItemToNothingAction());
                wazaSelectPanel.Show();
                msgWindowController.OpenMsgWindow(UIMsgWindowController.MessageFileType.Bag, QuestionRecoverWazaPPMessageLabel, false, true, null, null);
                return;
            }

            bool canUse;
            if (itemInfo.IsRecoveryPpAll)
            {
                canUse = false;
                for (byte i = 0; i < pokeParam.GetWazaCount(); i++)
                {
                    if (pokeParam.GetWazaPP(i) < pokeParam.GetWazaMaxPP(i))
                    {
                        canUse = true;
                        break;
                    }
                }
            }
            else if (itemInfo.Category == ItemInfo.CategoryType.Battle || itemInfo.Category == ItemInfo.CategoryType.Heal)
            {
                canUse = true;
            }
            else
            {
                canUse = CheckAndUseRecoveryItem(pokeParam, itemInfo, false, out RecoveryResultType resultType);
            }
            UseItem(canUse, -1);

            void UseItem(bool isUsable, int subSelectIndex)
            {
                // SHIPPED: isUsable is never read (@01be2330, w1 dead) — the item is handed to the battle either way
                EndSelectPokemonParty();
                if (modeType >= ModeType.Recovery && modeType <= ModeType.EquipOnly)
                {
                    UIManager.onUseItemInBattle?.Invoke(onlyViewBattlePokemonId, subSelectIndex, itemInfo);
                    UIManager.Instance.CloseXMenu(onClosed_ => Close(onClosed_, WINDOWID_FIELD, false));
                    return;
                }
                UIManager.onUseItemInBattle?.Invoke(index, subSelectIndex, itemInfo);
                Close(onClosed, _prevWindowId, false);
            }
        }
		private void OnPokemonPartyClickedToEquipItem(global::Dpr.UI.PokemonPartyItem pokemonPartyItem, int index) {
            PokemonParam pokeParam;
            ItemInfo itemInfo;
            ushort equippedItemId;
            Action onCloseWindow = null;
            if (modeType < ModeType.Recovery || modeType > ModeType.EquipOnly)
            {
                onCloseWindow = () =>
                {
                    msgWindowController.OpenMsgWindow(UIMsgWindowController.MessageFileType.Bag, QuestionWhichEquipItemMessageLabel, false, false, null, null);
                    pokemonParty.SetActive(true, true);
                };
            }

            pokeParam = pokemonPartyItem.param.pokemonParam;
            if (pokeParam.IsEgg(EggCheckType.BOTH_EGG))
            {
                msgWindowController.OpenMsgWindow(UIMsgWindowController.MessageFileType.Bag, DontEquipItemForEggMessageLabel, true, false, null, onCloseWindow);
                return;
            }

            itemInfo = bagItemPanel.SelectedItemButton.GetInfo();
            equippedItemId = pokeParam.GetItem();
            if (equippedItemId == 0)
            {
                pokeParam.SetItem((ushort)itemInfo.Id);
                ItemWork.SubItem(itemInfo.Id, 1);
                pokemonPartyItem.Setup(pokemonPartyItem.param);
                EndSelectPokemonParty();
                bagItemPanel.ReloadItemList(false, 0);
                Dpr.Message.MessageWordSetHelper.SetItemWord(0, itemInfo.Id, 1);
                msgWindowController.OpenMsgWindow(UIMsgWindowController.MessageFileType.Bag, EquipItemResultMessageLabel, true, false, null, () => EndItemEquip(pokemonPartyItem));
                return;
            }

            Dpr.Message.MessageWordSetHelper.SetItemWord(0, equippedItemId, 1);
            Dpr.Message.MessageWordSetHelper.SetItemWord(1, itemInfo.Id, 1);
            msgWindowController.OpenMsgWindow(UIMsgWindowController.MessageFileType.Bag, QuestionSwapItemMessageLabel, true, false, () =>
            {
                Dpr.MsgWindow.MsgWindowManager.OpenYesNoMenu(index2 =>
                {
                    EndSelectPokemonParty();
                    if (index2 != 0)
                        return;

                    if (!ItemWork.IsAddItem(equippedItemId, 1))
                    {
                        msgWindowController.OpenMsgWindow(UIMsgWindowController.MessageFileType.Bag, DontAddItemMessageLabel, true, false, null, () => EndItemEquip(pokemonPartyItem));
                        return;
                    }

                    ItemWork.AddItem(equippedItemId, 1);
                    pokeParam.SetItem((ushort)itemInfo.Id);
                    ItemWork.SubItem(itemInfo.Id, 1);
                    pokemonPartyItem.Setup(pokemonPartyItem.param);
                    bagItemPanel.ReloadItemList(false, 0);
                    Dpr.Message.MessageWordSetHelper.SetItemWord(0, equippedItemId, 1);
                    Dpr.Message.MessageWordSetHelper.SetItemWord(1, itemInfo.Id, 1);
                    msgWindowController.OpenMsgWindow(UIMsgWindowController.MessageFileType.Bag, SwapItemResultMessageLabel, true, false, null, () => EndItemEquip(pokemonPartyItem));
                }, ContextMenuWindow.CursorType.Arrow, true, true, null, AK.EVENTS.UI_COMMON_DECIDE);
            }, null);
        }
		private void EndItemEquip(global::Dpr.UI.PokemonPartyItem pokemonPartyItem) {
            PokemonParam pokemonParam = pokemonPartyItem.param.pokemonParam;
            ushort nextFormNo = pokemonParam.GetNextFormNoFromHoldItem(pokemonParam.GetItem());
            if (pokemonParam.GetFormNo() != nextFormNo && pokemonPartyItem.FormChange(nextFormNo, effectRoot, null, ShowFormChangeResult))
                isWaitUpdate = true;
        }
		public global::System.Collections.IEnumerator ResetBallTab() {
            bagItemPanel.CategorySelector.Setup(0);
            yield return null;
        }
		private global::System.Collections.IEnumerator StartAutoPilot(global::Dpr.Item.ItemInfo useItem) {
            WaitForSeconds waitOpenUI = new WaitForSeconds(1f);
            WaitForSeconds waitSelect = new WaitForSeconds(0.7f);
            // SHIPPED: a third WaitForSeconds(1f) is built and never used (@01be32f8); the first wait yields waitOpenUI
            WaitForSeconds waitStart = new WaitForSeconds(1f);
            yield return waitOpenUI;

            int targetCategoryId = (int)useItem.Category;
            while (bagItemPanel.CurrentCategoryId != targetCategoryId)
            {
                _input.SetAutoButton(MoveRightButton);
                yield return waitSelect;
            }

            int targetItemId = useItem.Id;
            while (bagItemPanel.SelectedItemButton.GetInfo().Id != targetItemId)
            {
                _input.SetAutoButton(MoveDownButton);
                yield return waitSelect;
            }

            _input.SetAutoButton(UIManager.ButtonA);
            yield return waitOpenUI;

            ContextMenuWindow contextMenu = null;
            while (contextMenu == null)
            {
                contextMenu = UIManager.Instance.GetCurrentUIWindow<ContextMenuWindow>();
                if (contextMenu != null)
                    break;
                yield return null;
            }

            contextMenu.InputController.SetAutoButton(UIManager.ButtonA);
            _input.inputEnabled = true;
        }
